"""Reproduce the initial motor-target/IK seed bug without physics stepping."""
from pathlib import Path
import argparse,json
import numpy as np
import mujoco as mj
from fourth_arm_object_feedback import ArmObjectFeedback
p=argparse.ArgumentParser();p.add_argument('--trial',type=Path,required=True);p.add_argument('--reference',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();report=json.loads((a.trial/'report.json').read_text());cfg=json.loads((a.trial/'source_sonic_config.json').read_text());m=mj.MjModel.from_binary_path(report['model']['path']);z=dict(np.load(a.trial/'physical_trace.npz'));hist=dict(np.load(a.trial/'sonic_contact_feedback.npz'));ref=dict(np.load(a.reference,allow_pickle=False));d=mj.MjData(m);d.qpos[:]=z['qpos'][0];d.qvel[:]=z['qvel'][0];mj.mj_forward(m,d);ctrl=z['ctrl'][0].copy();body_names=report['sonic']['body_joint_names'];body_aids=[mj.mj_name2id(m,mj.mjtObj.mjOBJ_ACTUATOR,'motor_'+n)for n in body_names];ctrl[body_aids]=hist['hybrid_policy_learned_body_target'][0];keys=['qpos','qvel','qfrc_applied','xfrc_applied','ctrl'];before={k:getattr(d,k).copy()for k in keys};results={}
